-- A waiter call keeps what the guests asked for (#180): `kinds` (the plain call is `{waiter}`) and
-- `last_called_at`, the newest request, from which the unanswered time counts. Generated by
-- drizzle-kit, then this comment and the backfill added by hand: a call made before this holds the
-- plain `waiter` kind and its one request's time.
-- The backfill runs with RLS not forced (as 0019 does): the owner on Supabase has no BYPASSRLS,
-- so under forced RLS the UPDATE would touch no rows.
ALTER TABLE "restro"."waiter_calls" ADD COLUMN "kinds" text[] DEFAULT '{waiter}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."waiter_calls" ADD COLUMN "last_called_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."waiter_calls" ADD CONSTRAINT "waiter_calls_kinds" CHECK (cardinality("restro"."waiter_calls"."kinds") >= 1 and "restro"."waiter_calls"."kinds" <@ array['waiter', 'bill', 'ice', 'water', 'glasses', 'clean_table', 'terminal']::text[]);--> statement-breakpoint
ALTER TABLE "restro"."waiter_calls" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
UPDATE "restro"."waiter_calls" SET "last_called_at" = "called_at";--> statement-breakpoint
ALTER TABLE "restro"."waiter_calls" FORCE ROW LEVEL SECURITY;
